public class LibraryMember { private String memberId; private int borrowLimit; private int booksBorrowed = 0; public LibraryMember(String memberId, int borrowLimit) { if (memberId == null || memberId.trim().isEmpty() || memberId.length() < 4) throw new IllegalArgumentException("Invalid memberId: must be at least 4 non-whitespace characters."); this.memberId = memberId; this.borrowLimit = borrowLimit; } public void borrowBook() { if (booksBorrowed < borrowLimit) booksBorrowed++; } public int getBooksBorrowed() { return booksBorrowed; } public String displayInfo() { return "General Member | Books Borrowed: " + booksBorrowed; } public static String enrollBatch(String[] memberIds, int borrowLimit) { int enrolled = 0, rejected = 0; for (String id : memberIds) { try { new LibraryMember(id, borrowLimit); enrolled++; } catch (IllegalArgumentException e) { rejected++; } } return "Enrolled: " + enrolled + " | Rejected: " + rejected; } public static void main(String[] args) { String[] batch = {"STU1", "LB1", "STU2", " ", "STU3"}; System.out.println(enrollBatch(batch, 3)); StudentMember s = new StudentMember("STU10", 3, "CSE"); s.borrowBook(); s.borrowBook(); System.out.println("Books Borrowed: " + s.getBooksBorrowed()); } }
class StudentMember extends LibraryMember { private String course; public StudentMember(String memberId, int borrowLimit, String course) { super(memberId, borrowLimit); this.course = course; } public String getCourse() { return course; } @Override public String displayInfo() { return "Student Member | Course: " + course + " | Books Borrowed: " + getBooksBorrowed(); } }